+1 for this feature. 
And here is a temporary solution using js:

```python
import streamlit as st

# Initialize session state if not already present
if "current_tab" not in st.session_state:
    st.session_state.current_tab = "Tab 1"


# Define a function to switch to a specific tab
def switch_to_tab(tab_name):
    js_code = f"""
    <script>
        // Select the tab container
        console.log("Switching to tab: {tab_name}")
        var tabContainer = window.parent.document.querySelector('.stTabs');
        
        // Select the tab buttons
        var tabButtons = tabContainer.querySelectorAll('[role="tab"]');
        
        // Find the button for the target tab and click it
        tabButtons.forEach(function(button) {{
            if (button.innerText.trim() === "{tab_name}") {{
                button.click();
            }}
        }});
    </script>
    """
    # Execute the JavaScript code
    st.components.v1.html(js_code, height=0, width=0)


# Define a variable for the target tab
target_tab = "Tab 2"

# Define a button, clicking which will switch to the target tab
if st.button(f"Switch to {target_tab}"):
    st.session_state.current_tab = target_tab
    switch_to_tab(target_tab)

# Create tabs
tab1, tab2 = st.tabs(["Tab 1", "Tab 2"])

# Display content based on the current tab
with tab1:
    if st.session_state.current_tab == "Tab 1":
        st.write("This is Tab 1")
with tab2:
    if st.session_state.current_tab == "Tab 2":
        st.write("This is Tab 2")

```

